var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
/*\
title: $:/plugins/huwiki/ai/image-view-widget.js
type: application/javascript
module-type: widget

Render ForgeShare per-wiki local image references; retain read-only legacy Drive links.
\*/
(function(){
"use strict";
var Widget=require('$:/core/modules/widgets/widget.js').widget;
var images=require('$:/plugins/huwiki/ai/image-replies.js');
function ImageView(tree,options){this.initialise(tree,options);}
ImageView.prototype=new Widget();
ImageView.prototype.render=function(parent,next){
  this.parentDomNode=parent;this.computeAttributes();
  this.source=this.getAttribute("source",this.getVariable("currentTiddler"));
  var t=this.wiki.getTiddler(this.source),box=this.document.createElement("div");
  box.className="huw-ai-output-image";parent.insertBefore(box,next);this.domNodes=[box];
  if(!t){box.textContent=aiUi.choose("Billedtiddleren findes ikke.","Image tiddler not found.");return;}
  var id=t.fields["ai-media-id"];
  if(!id){
    // Existing HUWiki Drive references are historical data. Do not call the retired Apps Script API.
    var legacyId=t.fields["av-file-id"];
    if(legacyId && /^[\w-]{10,160}$/.test(legacyId)){
      var note=this.document.createElement("p");
      note.textContent=aiUi.choose("Dette er en ældre Google Drive-reference fra HUWiki. Åbn originalen på Drive, hvis den stadig findes.",
        "This is a legacy HUWiki Google Drive reference. Open the original on Drive if it still exists.");
      box.appendChild(note);
      var link=this.document.createElement("a");
      link.href="https://drive.google.com/file/d/"+encodeURIComponent(legacyId)+"/view";
      link.target="_blank";link.rel="noopener noreferrer";
      link.textContent=aiUi.choose("Åbn gammel Drive-fil","Open legacy Drive file");
      box.appendChild(link);
      return;
    }
    box.textContent=aiUi.choose("Billedtiddleren mangler en lokal billedreference.","Image tiddler has no local media reference.");
    return;
  }
  var img=this.document.createElement("img");img.alt=t.fields.caption||this.source;box.appendChild(img);
  var status=this.document.createElement("p");status.textContent=aiUi.choose("Henter lokalt billede…","Loading local image…");box.appendChild(status);
  var retry=this.document.createElement("button");retry.textContent=aiUi.choose("Hent billede igen","Reload image");box.appendChild(retry);
  function load(){retry.disabled=true;images.loadSavedImage({mediaId:id}).then(function(url){
    img.src=url;status.textContent="";retry.hidden=true;
  },function(e){status.textContent=e.message||String(e);retry.disabled=false;retry.hidden=false;});}
  retry.addEventListener("click",load);load();
};
ImageView.prototype.refresh=function(changed){var attrs=this.computeAttributes();if(attrs.source||(changed&&changed[this.source])){this.refreshSelf();return true;}if(changed&&changed["$:/language"]){var root=this.domNodes&&this.domNodes[0],button=root&&root.querySelector("button"),status=root&&root.querySelector("p");if(button)button.textContent=aiUi.text("Hent billede igen");if(status)status.textContent=aiUi.message(status.textContent);if(root&&!button)root.textContent=aiUi.message(root.textContent);return true;}return false;};
exports['huwiki-ai-image']=ImageView;
})();
